        "dict-easton",
        "Dictionary",
        "Easton.",
        "<strong>Dictionary (Easton's).</strong> <strong>ANT</strong> (Hebrews nemalah, from a word meaning to creep, cut off, destroy), referred to in Proverbs 6:6; 30:25, as distinguished for its prudent habits. Many ants in Palestine feed on animal substances, but others draw their nourishment partly or exclusively from vegetables. To the latter class belongs the ant to which Solomon refers. This ant gathers the seeds in the season of ripening, and stores them for future use; a habit that has been observed in ants in Texas, India, and Italy. <em>[Reviewer: condense Easton's entry as needed.]</em>",
        "Easton's Illustrated Bible Dictionary, M. G. Easton (1897). Public domain.",
