        "dict-easton",
        "Dictionary",
        "Easton.",
        "<strong>Dictionary (Easton's).</strong> <strong>BLACK</strong> properly the absence of all colour. In Proverbs 7:9 the Hebrew word means, as in the margin of the Revised Version, “the pupil of the eye.” It is translated “apple” of the eye in Deuteronomy 32:10; Psalm 17:8; Proverbs 7:2. It is a different word which is rendered “black” in Leviticus 13:31,37; Cant. 1:5; 5:11; and Zechariah 6:2, 6. It is uncertain what the “black marble” of Esther 1:6 was which formed a part of the mosaic pavement. <em>[Reviewer: condense Easton's entry as needed.]</em>",
        "Easton's Illustrated Bible Dictionary, M. G. Easton (1897). Public domain.",
