        "<strong>Dictionary (Easton's).</strong> <strong>THORN</strong> (1.) Hebrews hedek (Proverbs 15:19), rendered “brier” in Micah 7:4. Some thorny plant, of the Solanum family, suitable for hedges. This is probably the so-called “apple of Sodom,” which grows very abundantly in the Jordan valley. “It is a shrubby plant, from 3 to 5 feet high, with very branching stems, thickly clad with spines, like those of the English brier, with leaves very large and woolly on the under side, and thorny on the midriff.” (2.) Hebrews kotz (Genesis 3:18;… <em>[Reviewer: condense Easton's entry as needed.]</em>",
