        "<strong>Dictionary (Easton's).</strong> <strong>NETTLE</strong> (1.) Hebrews haral, “pricking” or “burning,” Proverbs 24:30, 31 (R.V. marg., “wild vetches”); Job 30:7; Zephaniah 2:9. Many have supposed that some thorny or prickly plant is intended by this word, such as the bramble, the thistle, the wild plum, the cactus or prickly pear, etc. It may probably be a species of mustard, the Sinapis arvensis, which is a pernicious weed abounding in corn-fields. Tristram thinks that this word “designates the prickly acanthus (Acanthus… <em>[Reviewer: condense Easton's entry as needed.]</em>",
