        "<strong>Dictionary (Easton's).</strong> <strong>COAL I</strong> t is by no means certain that the Hebrews were acquainted with mineral coal, although it is found in Syria. Their common fuel was dried dung of animals and wood charcoal. Two different words are found in Hebrew to denote coal, both occurring in Proverbs 26:21, “As coal [Hebrews peham; i.e., “black coal”] is to burning coal [Hebrews gehalim].” The latter of these words is used in Job 41:21; Proverbs 6:28; Isaiah 44:19. The words “live coal” in Isaiah 6:6 are more correctly… <em>[Reviewer: condense Easton's entry as needed.]</em>",
