        "Easton.",
        "<strong>Dictionary (Easton's).</strong> <strong>CONEY</strong> (Hebrews shaphan; i.e., “the hider”), an animal which inhabits the mountain gorges and the rocky districts of Arabia Petraea and the Holy Land. “The conies are but a feeble folk, yet make they their houses in the rocks” (Proverbs 30:26; Psalm 104:18). They are gregarious, and “exceeding wise” (Proverbs 30:24), and are described as chewing the cud (Leviticus 11:5; Deuteronomy 14:7). The animal intended by this name is known among naturalists as the Hyrax Syriacus. It is… <em>[Reviewer: condense Easton's entry as needed.]</em>",
