        "Easton.",
        "<strong>Dictionary (Easton's).</strong> <strong>GREYHOUND</strong> (Proverbs 30:31), the rendering of the Hebrew zarzir mothnayim, meaning literally “girded as to the lions.” Some (Gesen.; R.V. marg.) render it “war-horse.” The LXX. and Vulgate versions render it “cock.” It has been by some interpreters rendered also “stag” and “warrior,” as being girded about or panoplied, and “wrestler.” The greyhound, however, was evidently known in ancient times, as appears from Egyptian monuments. <em>[Reviewer: condense Easton's entry as needed.]</em>",
        "Easton's Illustrated Bible Dictionary, M. G. Easton (1897). Public domain.",
